#include <stddef.h>
#include <stdint.h>
#define N 12
#define L 26
static void put64(uint8_t*o,size_t p,int64_t x){uint64_t b=(uint64_t)x;for(size_t j=0;j<8;j++){o[p+j]=(uint8_t)(b&255U);b>>=8;}}
int64_t srpt_flow_time(const int64_t*in,size_t len,uint8_t*out,size_t cap){if(!in||len<4||len>L)return -1;int64_t mr=in[0],nr=in[1];if(mr<1||mr>4||nr<1||nr>N||len!=2+2*(size_t)nr)return -1;size_t machines=(size_t)mr,n=(size_t)nr;int64_t release[N],remaining[N],completion[N];for(size_t i=0;i<n;i++){release[i]=in[2+2*i];remaining[i]=in[3+2*i];if(release[i]<0||release[i]>50||remaining[i]<1||remaining[i]>10)return -1;}size_t bytes=8*(1+n);if(!out||cap<bytes)return -2;int64_t time=0;size_t finished=0;while(finished<n){size_t selected[N],selected_count=0;uint8_t chosen[N]={0};for(size_t machine=0;machine<machines;machine++){size_t best=n;for(size_t i=0;i<n;i++)if(!chosen[i]&&remaining[i]>0&&release[i]<=time&&(best==n||remaining[i]<remaining[best]||(remaining[i]==remaining[best]&&i<best)))best=i;if(best==n)break;chosen[best]=1;selected[selected_count++]=best;}if(selected_count==0){int64_t next=INT64_MAX;for(size_t i=0;i<n;i++)if(remaining[i]>0&&release[i]<next)next=release[i];time=next;continue;}time++;for(size_t j=0;j<selected_count;j++){size_t i=selected[j];remaining[i]--;if(remaining[i]==0){completion[i]=time;finished++;}}}int64_t total=0;for(size_t i=0;i<n;i++)total+=completion[i]-release[i];put64(out,0,total);for(size_t i=0;i<n;i++)put64(out,8*(1+i),completion[i]);return (int64_t)bytes;}
